#!/usr/bin/env python3
"""Generate twiddle_rom.v: cos/sin(2*pi*k/N) for k < N/2, N = 2**LOG2N_MAX.

Entries are 18-bit signed, 16 fractional bits (1.0 = 65536), packed {cos, sin}.
Run again only if LOG2N_MAX in myfft_axil.v changes:  python3 gen_twiddle.py 10
"""
import math
import sys

log2n = int(sys.argv[1]) if len(sys.argv) > 1 else 10
n = 1 << log2n
half = n // 2
aw = log2n - 1


def q18(v):
    return round(v * 65536) & 0x3FFFF


lines = [
    "`timescale 1ns / 1ps",
    "// twiddle_rom.v - GENERATED by gen_twiddle.py, do not edit.",
    f"// q = {{cos, sin}}(2*pi*k/{n}), 18-bit signed each, 16 fractional bits.",
    "module twiddle_rom (",
    "    input  wire        clk,",
    "    input  wire        en,",
    f"    input  wire [{aw - 1}:0] k,",
    "    output reg  [35:0] q",
    ");",
    "    always @(posedge clk) begin",
    "        if (en) begin",
    "            case (k)",
]
for k in range(half):
    a = 2 * math.pi * k / n
    word = (q18(math.cos(a)) << 18) | q18(math.sin(a))
    lines.append(f"                {aw}'d{k}: q <= 36'h{word:09x};")
lines += [
    "                default: q <= 36'h0;",
    "            endcase",
    "        end",
    "    end",
    "endmodule",
    "",
]
with open("twiddle_rom.v", "w") as f:
    f.write("\n".join(lines))
print(f"twiddle_rom.v: {half} entries for N = {n}")
